const crypto = require('node:crypto');
const { promisify } = require('node:util');
const express = require('express');
const session = require('express-session');

const scrypt = promisify(crypto.scrypt);

if (!process.env.SESSION_SECRET) throw new Error('SESSION_SECRET is required');

// --- password hashing (stdlib scrypt, per-user random salt) ---

async function hashPassword(password) {
  const salt = crypto.randomBytes(16);
  const key = await scrypt(password, salt, 64);
  return `${salt.toString('hex')}:${key.toString('hex')}`;
}

async function verifyPassword(password, stored) {
  const [salt, key] = stored.split(':').map((h) => Buffer.from(h, 'hex'));
  return crypto.timingSafeEqual(key, await scrypt(password, salt, 64));
}

// --- users ---

// ponytail: in-memory users, swap for a DB table (username unique, hash text) when you have one
const users = new Map();

async function createUser(username, password) {
  users.set(username.toLowerCase(), { hash: await hashPassword(password) });
}

// Verified against when the username doesn't exist, so response time doesn't reveal which usernames are real.
const dummyHash = hashPassword(crypto.randomBytes(16).toString('hex'));

// --- rate limiting of failed logins ---

const WINDOW_MS = 15 * 60 * 1000;
// Per-username stops guessing one account from many IPs; per-IP stops spraying many accounts from one.
const LIMITS = { user: 5, ip: 20 };

// ponytail: in-memory, per-process fixed window. Move to Redis (INCR + EXPIRE) when running more than one instance.
const attempts = new Map(); // key -> { count, resetAt }

function hit(key) {
  const now = Date.now();
  let entry = attempts.get(key);
  if (!entry || entry.resetAt <= now) attempts.set(key, (entry = { count: 0, resetAt: now + WINDOW_MS }));
  entry.count++;
  return entry;
}

setInterval(() => {
  const now = Date.now();
  for (const [key, entry] of attempts) if (entry.resetAt <= now) attempts.delete(key);
}, WINDOW_MS).unref();

// --- app ---

const app = express();
// Behind a reverse proxy, uncomment so req.ip is the client and secure cookies work:
// app.set('trust proxy', 1);
app.use(express.json({ limit: '10kb' }));
app.use(
  session({
    // ponytail: default MemoryStore leaks and is single-process, use connect-redis / connect-pg-simple in production
    secret: process.env.SESSION_SECRET,
    resave: false,
    saveUninitialized: false,
    cookie: {
      httpOnly: true,
      sameSite: 'lax',
      secure: process.env.NODE_ENV === 'production',
      maxAge: 24 * 60 * 60 * 1000,
    },
  })
);

app.post('/login', async (req, res, next) => {
  try {
    const { username, password } = req.body ?? {};
    if (
      typeof username !== 'string' || typeof password !== 'string' ||
      !username || !password || username.length > 64 || password.length > 1024
    ) {
      return res.status(400).json({ error: 'username and password required' });
    }
    const name = username.toLowerCase();

    // Count the attempt before the (slow, async) hash check so a burst of parallel
    // requests can't all slip past the limit; refunded below on success.
    const ipEntry = hit(`ip:${req.ip}`);
    const userEntry = hit(`user:${name}`);
    const blocked = [ipEntry.count > LIMITS.ip && ipEntry, userEntry.count > LIMITS.user && userEntry].find(Boolean);
    if (blocked) {
      res.set('Retry-After', String(Math.ceil((blocked.resetAt - Date.now()) / 1000)));
      return res.status(429).json({ error: 'too many failed attempts, try again later' });
    }

    const user = users.get(name);
    const ok = await verifyPassword(password, user ? user.hash : await dummyHash);
    if (!user || !ok) return res.status(401).json({ error: 'invalid username or password' });

    ipEntry.count--;
    attempts.delete(`user:${name}`);

    // New session id on login prevents session fixation.
    req.session.regenerate((err) => {
      if (err) return next(err);
      req.session.user = name;
      res.json({ user: name });
    });
  } catch (err) {
    next(err);
  }
});

app.post('/logout', (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie('connect.sid');
    res.status(204).end();
  });
});

function requireLogin(req, res, next) {
  if (!req.session.user) return res.status(401).json({ error: 'not logged in' });
  next();
}

app.get('/me', requireLogin, (req, res) => res.json({ user: req.session.user }));

if (require.main === module) {
  const port = process.env.PORT || 3000;
  app.listen(port, () => console.log(`listening on :${port}`));
}

module.exports = { app, createUser };

process.env.SESSION_SECRET = 'test-secret';
const assert = require('node:assert');
const { test, before, after } = require('node:test');
const { app, createUser } = require('./server');

let server, base;

before(async () => {
  await createUser('alice', 'correct horse');
  await createUser('bob', 'battery staple');
  server = app.listen(0);
  base = `http://127.0.0.1:${server.address().port}`;
});
after(() => server.close());

const login = (username, password) =>
  fetch(`${base}/login`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ username, password }),
  });

test('login, session, logout', async () => {
  assert.equal((await fetch(`${base}/me`)).status, 401);
  assert.equal((await login('alice', 'wrong')).status, 401);
  assert.equal((await login('nobody', 'wrong')).status, 401);
  assert.equal((await login('alice')).status, 400);

  const res = await login('alice', 'correct horse');
  assert.equal(res.status, 200);
  const cookie = res.headers.get('set-cookie').split(';')[0];
  assert.match(res.headers.get('set-cookie'), /HttpOnly/);

  const me = await fetch(`${base}/me`, { headers: { cookie } });
  assert.deepEqual(await me.json(), { user: 'alice' });

  assert.equal((await fetch(`${base}/logout`, { method: 'POST', headers: { cookie } })).status, 204);
  assert.equal((await fetch(`${base}/me`, { headers: { cookie } })).status, 401);
});

test('locks out after 5 failed attempts, even with the right password', async () => {
  // fired in parallel on purpose: the limit must hold under a burst
  const statuses = await Promise.all(Array.from({ length: 8 }, () => login('bob', 'wrong').then((r) => r.status)));
  assert.equal(statuses.filter((s) => s === 401).length, 5);
  assert.equal(statuses.filter((s) => s === 429).length, 3);

  const res = await login('bob', 'battery staple');
  assert.equal(res.status, 429);
  assert.ok(Number(res.headers.get('retry-after')) > 0);
});

